mapper.select:
SELECT e.*,(SELECT COUNT(*) FROM biz_extension_class_member m JOIN biz_student s ON s.student_id=m.student_id JOIN sys_user u ON u.user_id=s.user_id AND u.status='0' AND u.del_flag='0' WHERE m.extension_class_id=e.extension_class_id) member_count
FROM biz_extension_class e WHERE e.dept_id=#{deptId}
AND e.owner_user_id=#{ownerId}
ORDER BY e.status,e.extension_class_id DESC
